5 An unqualified name that is a component name (7.5.4.2) of a type-specifier or ptr-operator of a conversiontype-id is looked up in the same fashion as the conversion-function-id in which it appears. If that lookup finds nothing, it undergoes unqualified name lookup; in each case, only names that denote types or templates whose specializations are types are considered.

```cpp
struct T1 { struct U { int i; }; };
struct T2 { };
struct U1 {};
struct U2 {}

struct B {
    using T = T1;
    using U = U1;
    operator U1 T1::*();
    operator U1 T2::*();
    operator U2 T1::*();
    operator U2 T2::*();
};

template<class X, class T>
int g() {
    using U = U2;
    X().operator U T::*();          // #1, searches for T in the scope of X first
    X().operator U decltype(T())::*();   // #2
    return 0;
}
int x = g<B, T2>();
// #1 calls B::operator U1 T1::*
// #2 calls B::operator U1 T2::*

