template<typename T> class atomic_list {
    struct node {
        T t;
        shared_ptr<node> next;
    };
    atomic<shared_ptr<node>> head;

public:
    shared_ptr<node> find(T t) const {
        auto p = head.load();
        while (p && p->t != t)
            p = p->next;

        return p;
    }

    void push_front(T t) {
        auto p = make_shared<node>();
