b0.arrive();
b0.arrive();          // implementation-defined; previously well-defined

int data = 0;
auto b1 = std::barrier(1, [&] { data++; });
b1.arrive();
assert(data == 1);      // implementation-defined; previously well-defined
b1.arrive();          // implementation-defined; previously well-defined

